SELECT
FROM AR_MAC_CARDS_LINK A JOIN HR_EMPLOYEE B ON A.PERSON_ID = B.PERSON_ID WHERE B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND ( B.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR CONVERTTOUNSIGN(UPPER(B.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%' OR UPPER(B.ENGLISH_NAME) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%' )
AND A.ACTIVITY = #{filterActivity, jdbcType=VARCHAR}
ORDER BY B.EMPID ASC, A.RECORD_NO DESC

SELECT

FROM AR_MAC_CARDS_LINK A
JOIN HR_EMPLOYEE B ON A.PERSON_ID = B.PERSON_ID
WHERE A.RECORD_NO = #{recordNo, jdbcType=NUMERIC}
  AND B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
